%{
[rows, cols] = size(M);

% Initialize a cell array to hold each row string
mathematicaRows = cell(rows, 1);

for i = 1:rows
    rowElements = cell(1, cols);
    for j = 1:cols
        % Extract element and convert to string
        elemStr = char(M(i, j));
        
        % 1. Clean up underscores so variables don't break patterns
        elemStr = replace(elemStr, '_', '');
        
        % 2. Regex conversion: Change function(arg) to Function[arg]
        % This forces MATLAB's lowercase 'sin(something)' into 'Sin[something]'
        elemStr = regexprep(elemStr, 'sin\((.*?)\)', 'Sin[$1]');
        elemStr = regexprep(elemStr, 'cos\((.*?)\)', 'Cos[$1]');
        elemStr = regexprep(elemStr, 'tan\((.*?)\)', 'Tan[$1]');
        elemStr = regexprep(elemStr, 'sqrt\((.*?)\)', 'Sqrt[$1]');
        elemStr = regexprep(elemStr, 'exp\((.*?)\)', 'Exp[$1]');
        
        rowElements{j} = elemStr;
    end
    mathematicaRows{i} = ['{', strjoin(rowElements, ', '), '}'];
end


% Join all rows together wrapped in an outer set of braces
finalMathematicaMatrix = ['{', strjoin(mathematicaRows, ', '), '}'];

% Save this flawless string to your directory
fid = fopen('matrix_for_mathematica_M.txt', 'w');
fprintf(fid, '%s', finalMathematicaMatrix);
fclose(fid);

